ketal-01.sql:
SELECT p.categoria, SUM(h.cantidad) AS unidades
FROM hecho_venta h JOIN dim_producto p ON h.id_producto = p.id_producto
GROUP BY p.categoria ORDER BY unidades DESC;

ketal-05.sql:
SELECT t.trimestre, ROUND((SUM(h.importe))::numeric, 2) AS importe
FROM hecho_venta h JOIN dim_tiempo t ON h.id_tiempo = t.id_tiempo
WHERE t.anio = 2025 GROUP BY t.trimestre ORDER BY t.trimestre;

ketal-09.sql:
SELECT mes, importe, ROUND((SUM(importe) OVER (ORDER BY mes))::numeric, 2) AS acumulado
FROM (
  SELECT t.mes AS mes, ROUND((SUM(h.importe))::numeric, 2) AS importe
  FROM hecho_venta h JOIN dim_tiempo t ON h.id_tiempo = t.id_tiempo
  WHERE t.anio = 2025 GROUP BY t.mes
) ORDER BY mes;

tel-01.sql:
SELECT l.color, COUNT(*) AS viajes
FROM hecho_viaje h JOIN dim_linea l ON h.id_linea = l.id_linea
GROUP BY l.color ORDER BY viajes DESC;

tel-05.sql:
SELECT t.dia_semana, COUNT(*) AS viajes
FROM hecho_viaje h JOIN dim_tiempo t ON h.id_tiempo = t.id_tiempo
GROUP BY t.dia_semana ORDER BY viajes DESC;

tel-06.sql:
SELECT l.color, ROUND((AVG(h.duracion_min))::numeric, 1) AS minutos
FROM hecho_viaje h JOIN dim_linea l ON h.id_linea = l.id_linea
GROUP BY l.color ORDER BY minutos DESC;

tel-07.sql:
SELECT l.color, ROUND((SUM(h.es_transbordo) * 100.0 / COUNT(*))::numeric, 2) AS pct_transbordo
FROM hecho_viaje h JOIN dim_linea l ON h.id_linea = l.id_linea
GROUP BY l.color ORDER BY pct_transbordo DESC;

tel-08.sql:
SELECT t.nombre_mes, COUNT(*) AS viajes, ROUND((SUM(h.tarifa_pagada))::numeric, 2) AS recaudacion
FROM hecho_viaje h JOIN dim_tiempo t ON h.id_tiempo = t.id_tiempo
GROUP BY t.mes, t.nombre_mes ORDER BY t.mes;

tel-10.sql:
SELECT mes, viajes, ROUND((AVG(viajes) OVER (ORDER BY mes ROWS BETWEEN 2 PRECEDING AND CURRENT ROW))::numeric, 1) AS media_movil
FROM (
  SELECT t.mes AS mes, COUNT(*) AS viajes
  FROM hecho_viaje h JOIN dim_tiempo t ON h.id_tiempo = t.id_tiempo
  GROUP BY t.mes
) ORDER BY mes;

tel-11.sql:
SELECT p.tipo, ROUND((AVG(h.tarifa_pagada))::numeric, 2) AS tarifa_promedio
FROM hecho_viaje h JOIN dim_pasajero p ON h.id_tipo_pasajero = p.id_tipo_pasajero
GROUP BY p.tipo ORDER BY tarifa_promedio DESC;

bso-01.sql:
SELECT p.nombre, ROUND((SUM(d.monto))::numeric, 2) AS monto
FROM hecho_desembolso d JOIN dim_producto p ON d.id_producto = p.id_producto
GROUP BY p.nombre ORDER BY monto DESC;

bso-02.sql:
SELECT a.ciudad, COUNT(*) AS clientes
FROM dim_cliente c JOIN dim_agencia a ON c.id_agencia = a.id_agencia
GROUP BY a.ciudad ORDER BY clientes DESC;

bso-03.sql:
SELECT t.mes, ROUND((SUM(d.monto))::numeric, 2) AS monto
FROM hecho_desembolso d JOIN dim_tiempo t ON d.id_tiempo = t.id_tiempo
GROUP BY t.mes ORDER BY t.mes;

bso-05.sql:
SELECT t.mes, ROUND((SUM(s.saldo_cartera))::numeric, 2) AS saldo
FROM hecho_saldo_mes s JOIN dim_tiempo t ON s.id_tiempo = t.id_tiempo
GROUP BY t.mes ORDER BY t.mes;

bso-06.sql:
SELECT ROUND((SUM(s.saldo_cartera))::numeric, 2) AS cartera_final
FROM hecho_saldo_mes s JOIN dim_tiempo t ON s.id_tiempo = t.id_tiempo
WHERE t.mes = (SELECT MAX(t2.mes) FROM hecho_saldo_mes s2 JOIN dim_tiempo t2 ON s2.id_tiempo = t2.id_tiempo);

bso-07.sql:
SELECT ROUND((AVG(saldo))::numeric, 2) AS saldo_promedio FROM (
  SELECT t.mes AS mes, SUM(s.saldo_cartera) AS saldo
  FROM hecho_saldo_mes s JOIN dim_tiempo t ON s.id_tiempo = t.id_tiempo
  GROUP BY t.mes
);

bso-09.sql:
SELECT mes, saldo, LAG(saldo) OVER (ORDER BY mes) AS saldo_anterior FROM (
  SELECT t.mes AS mes, ROUND((SUM(s.saldo_cartera))::numeric, 2) AS saldo
  FROM hecho_saldo_mes s JOIN dim_tiempo t ON s.id_tiempo = t.id_tiempo
  GROUP BY t.mes
) ORDER BY mes;

bso-12.sql:
SELECT t.mes, ROUND((SUM(s.saldo_mora) * 100.0 / SUM(s.saldo_cartera))::numeric, 2) AS indice_mora
FROM hecho_saldo_mes s JOIN dim_tiempo t ON s.id_tiempo = t.id_tiempo
GROUP BY t.mes ORDER BY t.mes;

ai-01.sql:
SELECT e.nombre, COUNT(*) AS atenciones, ROUND((SUM(a.importe))::numeric, 2) AS importe
FROM hecho_atencion a JOIN dim_especialidad e ON a.id_especialidad = e.id_especialidad
GROUP BY e.nombre ORDER BY importe DESC;

ai-04.sql:
SELECT p.zona, COUNT(*) AS atenciones
FROM hecho_atencion a JOIN dim_paciente p ON a.id_version_paciente = p.id_version
GROUP BY p.zona ORDER BY atenciones DESC, p.zona;

ai-07.sql:
SELECT p.seguro, ROUND((SUM(a.importe))::numeric, 2) AS importe
FROM hecho_atencion a JOIN dim_paciente p ON a.id_version_paciente = p.id_version
GROUP BY p.seguro ORDER BY importe DESC;

ai-08.sql:
SELECT e.area, ROUND((SUM(a.importe))::numeric, 2) AS importe
FROM hecho_atencion a JOIN dim_especialidad e ON a.id_especialidad = e.id_especialidad
GROUP BY e.area ORDER BY importe DESC;

ai-09.sql:
SELECT t.nombre_mes, COUNT(*) AS atenciones
FROM hecho_atencion a JOIN dim_tiempo t ON a.id_tiempo = t.id_tiempo
GROUP BY t.mes, t.nombre_mes ORDER BY t.mes;

ygo-01.sql:
SELECT c.categoria, COUNT(*) AS pedidos, ROUND((SUM(p.subtotal))::numeric, 2) AS subtotal
FROM hecho_pedido p JOIN dim_comercio c ON p.id_comercio = c.id_comercio
GROUP BY c.categoria ORDER BY subtotal DESC;

ygo-02.sql:
SELECT z.nombre AS zona, COUNT(*) AS envios, ROUND((AVG(e.minutos_entrega))::numeric, 1) AS minutos
FROM hecho_envio e JOIN dim_zona z ON e.id_zona = z.id_zona
GROUP BY z.nombre ORDER BY minutos DESC;

ygo-07.sql:
SELECT rp.vehiculo, ROUND((AVG(e.minutos_entrega))::numeric, 1) AS minutos, COUNT(*) AS envios
FROM hecho_envio e JOIN dim_repartidor rp ON e.id_repartidor = rp.id_repartidor
GROUP BY rp.vehiculo ORDER BY minutos DESC;

ygo-08.sql:
SELECT t.dia_semana, COUNT(*) AS pedidos
FROM hecho_pedido p JOIN dim_tiempo t ON p.id_tiempo = t.id_tiempo
GROUP BY t.dia_semana ORDER BY pedidos DESC;

ygo-09.sql:
SELECT t.mes, COUNT(*) AS pedidos, ROUND((SUM(p.subtotal))::numeric, 2) AS subtotal
FROM hecho_pedido p JOIN dim_tiempo t ON p.id_tiempo = t.id_tiempo
GROUP BY t.mes ORDER BY t.mes;

ygo-10.sql:
SELECT RANK() OVER (ORDER BY subtotal DESC) AS puesto, nombre, subtotal FROM (
  SELECT c.nombre AS nombre, ROUND((SUM(p.subtotal))::numeric, 2) AS subtotal
  FROM hecho_pedido p JOIN dim_comercio c ON p.id_comercio = c.id_comercio
  GROUP BY c.nombre
) ORDER BY subtotal DESC LIMIT 5;

ygo-12.sql:
SELECT rp.alias, COUNT(*) AS envios, ROUND((SUM(e.distancia_km))::numeric, 2) AS km, ROUND((SUM(e.propina))::numeric, 2) AS propina
FROM hecho_envio e JOIN dim_repartidor rp ON e.id_repartidor = rp.id_repartidor
GROUP BY rp.alias ORDER BY km DESC, rp.alias LIMIT 8;

ent-01.sql:
SELECT pl.nombre AS plan, ROUND((SUM(c.datos_gb))::numeric, 2) AS datos_gb
FROM hecho_consumo_dia c JOIN dim_plan pl ON c.id_plan = pl.id_plan
GROUP BY pl.nombre ORDER BY datos_gb DESC;

ent-02.sql:
SELECT pl.nombre AS plan, ROUND((SUM(a.datos_gb))::numeric, 2) AS datos_gb
FROM agregado_consumo_mes a JOIN dim_plan pl ON a.id_plan = pl.id_plan
GROUP BY pl.nombre ORDER BY datos_gb DESC;

ent-03.sql:
SELECT t.dia_semana, ROUND((SUM(c.datos_gb))::numeric, 2) AS datos_gb
FROM hecho_consumo_dia c JOIN dim_tiempo t ON c.id_tiempo = t.id_tiempo
GROUP BY t.dia_semana ORDER BY datos_gb DESC;

ent-04.sql:
SELECT
  (SELECT COUNT(*) FROM hecho_consumo_dia) AS filas_detalle,
  (SELECT COUNT(*) FROM agregado_consumo_mes) AS filas_agregado;

ent-07.sql:
SELECT rg.nombre AS region, COUNT(DISTINCT c.id_linea) AS lineas
FROM hecho_consumo_dia c JOIN dim_region rg ON c.id_region = rg.id_region
GROUP BY rg.nombre ORDER BY lineas DESC, rg.nombre;

ent-08.sql:
SELECT pl.nombre AS plan, ROUND((SUM(c.datos_gb) / COUNT(DISTINCT c.id_linea))::numeric, 2) AS gb_por_linea
FROM hecho_consumo_dia c JOIN dim_plan pl ON c.id_plan = pl.id_plan
GROUP BY pl.nombre ORDER BY gb_por_linea DESC;

ent-10.sql:
SELECT region, datos_gb, ROUND((datos_gb * 100.0 / SUM(datos_gb) OVER ())::numeric, 2) AS participacion FROM (
  SELECT rg.nombre AS region, ROUND((SUM(a.datos_gb))::numeric, 2) AS datos_gb
  FROM agregado_consumo_mes a JOIN dim_region rg ON a.id_region = rg.id_region
  GROUP BY rg.nombre
) ORDER BY datos_gb DESC;

upb-07.sql:
SELECT p.codigo, COUNT(*) AS inscripciones, COUNT(DISTINCT i.id_estudiante) AS estudiantes
FROM hecho_inscripcion i JOIN dim_periodo p ON i.id_periodo = p.id_periodo
GROUP BY p.codigo ORDER BY p.codigo;

cin-01.sql:
SELECT p.titulo, COUNT(*) AS asistentes
FROM hecho_asistencia a JOIN dim_pelicula p ON a.id_pelicula = p.id_pelicula
GROUP BY p.titulo ORDER BY asistentes DESC, p.titulo LIMIT 10;

cin-02.sql:
SELECT c.nombre AS ciclo, COUNT(*) AS asistentes
FROM hecho_asistencia a JOIN dim_ciclo c ON a.id_ciclo = c.id_ciclo
GROUP BY c.nombre ORDER BY asistentes DESC;

cin-04.sql:
SELECT p.titulo, COUNT(DISTINCT a.id_funcion) AS funciones, COUNT(*) AS asistentes
FROM hecho_asistencia a JOIN dim_pelicula p ON a.id_pelicula = p.id_pelicula
GROUP BY p.titulo ORDER BY asistentes DESC, p.titulo LIMIT 10;

cin-07.sql:
SELECT pu.tipo, COUNT(*) AS asistentes, ROUND((COUNT(*) * pu.precio)::numeric, 2) AS recaudacion
FROM hecho_asistencia a JOIN dim_publico pu ON a.id_publico = pu.id_publico
GROUP BY pu.tipo, pu.precio ORDER BY recaudacion DESC;

cin-08.sql:
SELECT sala, capacidad, ROUND((AVG(pct))::numeric, 2) AS ocupacion_pct FROM (
  SELECT s.nombre AS sala, s.capacidad AS capacidad, COUNT(*) * 100.0 / s.capacidad AS pct
  FROM hecho_asistencia a JOIN dim_sala s ON a.id_sala = s.id_sala
  GROUP BY a.id_funcion, s.nombre, s.capacidad
) GROUP BY sala, capacidad ORDER BY ocupacion_pct DESC;

cin-09.sql:
SELECT t.nombre_mes, COUNT(*) AS asistentes
FROM hecho_asistencia a JOIN dim_tiempo t ON a.id_tiempo = t.id_tiempo
GROUP BY t.mes, t.nombre_mes ORDER BY t.mes;

cin-10.sql:
SELECT t.dia_semana, COUNT(*) AS asistentes
FROM hecho_asistencia a JOIN dim_tiempo t ON a.id_tiempo = t.id_tiempo
GROUP BY t.dia_semana ORDER BY asistentes DESC;

cin-11.sql:
SELECT ciclo, asistentes, ROUND((asistentes * 100.0 / SUM(asistentes) OVER ())::numeric, 2) AS participacion FROM (
  SELECT c.nombre AS ciclo, COUNT(*) AS asistentes
  FROM hecho_asistencia a JOIN dim_ciclo c ON a.id_ciclo = c.id_ciclo
  GROUP BY c.nombre
) ORDER BY asistentes DESC;
